using System;
using System.Diagnostics;
using System.IO;
using System.Windows.Forms;

namespace StudentHubSetup
{
    static class Program
    {
        // Embedded standalone launcher binary base64
        private const string EmbeddedLauncherBase64 = "";

        [STAThread]
        static void Main()
        {
            try
            {
                string appDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "StudentHub");
                if (!Directory.Exists(appDir))
                {
                    Directory.CreateDirectory(appDir);
                }

                string targetExePath = Path.Combine(appDir, "Student-Hub-Admin.exe");
                string currentDir = AppDomain.CurrentDomain.BaseDirectory;
                string sourceExe = Path.Combine(currentDir, "Student-Hub-Admin.exe");

                // If local file exists, copy it; otherwise decode from embedded payload
                if (File.Exists(sourceExe))
                {
                    File.Copy(sourceExe, targetExePath, true);
                }
                else
                {
                    byte[] binaryData = Convert.FromBase64String(EmbeddedLauncherBase64);
                    File.WriteAllBytes(targetExePath, binaryData);
                }

                // Create Desktop & Start Menu Shortcuts via PowerShell COM
                string desktopFolder = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
                string startMenuFolder = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs");

                string desktopLnk = Path.Combine(desktopFolder, "Student Hub - إدارة السنتر.lnk");
                string startMenuLnk = Path.Combine(startMenuFolder, "Student Hub.lnk");

                string psCmd = string.Format(
                    @"$ws = New-Object -ComObject WScript.Shell; " +
                    @"$s1 = $ws.CreateShortcut('{0}'); $s1.TargetPath = '{1}'; $s1.Description = 'نظام إدارة السنتر الذكي والتحضير السحابي'; $s1.Save(); " +
                    @"$s2 = $ws.CreateShortcut('{2}'); $s2.TargetPath = '{1}'; $s2.Description = 'نظام إدارة السنتر الذكي والتحضير السحابي'; $s2.Save();",
                    desktopLnk.Replace("'", "''"),
                    targetExePath.Replace("'", "''"),
                    startMenuLnk.Replace("'", "''")
                );

                ProcessStartInfo psi = new ProcessStartInfo("powershell.exe", "-NoProfile -ExecutionPolicy Bypass -Command \"" + psCmd + "\"")
                {
                    WindowStyle = ProcessWindowStyle.Hidden,
                    CreateNoWindow = true,
                    UseShellExecute = false
                };
                Process.Start(psi).WaitForExit();

                // Launch the installed app immediately
                if (File.Exists(targetExePath))
                {
                    Process.Start(targetExePath);
                }

                MessageBox.Show(
                    "تم تثبيت برنامج إدارة السنتر الذكي بنجاح على جهازك! ✅\n\n- تم تشغيل البرنامج الآن بنجاح.\n- تم إنشاء اختصار دائم على سطح المكتب (Desktop).\n- تم إنشاء اختصار في قائمة ابدأ (Start Menu).",
                    "Student Hub Setup",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information
                );
            }
            catch (Exception ex)
            {
                MessageBox.Show("حدث خطأ أثناء التثبيت: " + ex.Message, "Student Hub Setup", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }
}
